import {validateCourse} from './core.js';
export async function sha256(blob){const bytes=await blob.arrayBuffer();const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');}
export async function readBundle(x){if(!x||x.schema!=='tingyiju-bundle'||x.version!==1)throw Error('课程包格式不正确');const course=validateCourse(x.course),m=x.media;if(!m||typeof m.name!=='string'||m.name.length>1000||typeof m.type!=='string'||!/^(audio|video)\/[a-z0-9.+-]+$/i.test(m.type)||typeof m.base64!=='string'||m.base64.length>22*1024*1024||!/^[A-Za-z0-9+/]*={0,2}$/.test(m.base64)||typeof m.sha256!=='string'||!/^[a-f0-9]{64}$/.test(m.sha256))throw Error('课程包中的媒体格式无效或过大');let text;try{text=atob(m.base64);}catch{throw Error('媒体数据无法解码');}const bytes=new Uint8Array(text.length);for(let i=0;i<text.length;i++)bytes[i]=text.charCodeAt(i);const blob=new Blob([bytes],{type:m.type});const actual=await sha256(blob);if(actual!==m.sha256||course.mediaSha256&&actual!==course.mediaSha256)throw Error('媒体校验不一致，课程包未导入');course.mediaSha256=actual;course.mediaName=m.name;return {course,media:{blob,name:m.name}};}
export async function createBundle(course,media){if(!media)throw Error('这份课程尚未导入录音');if(media.blob.size>15*1024*1024)throw Error('一键课程包支持 15 MB 内的录音；更大文件请分别导出课程并保留媒体。');const bytes=new Uint8Array(await media.blob.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=8192)text+=String.fromCharCode(...bytes.subarray(i,i+8192));const hash=await sha256(media.blob);return {schema:'tingyiju-bundle',version:1,course:{...course,mediaName:media.name,mediaSha256:hash},media:{name:media.name,type:media.blob.type||'audio/ogg',base64:btoa(text),sha256:hash}};}
